<?php
declare(strict_types=1);
$news = is_array($news ?? null) ? $news : [];
?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Noticias</h1><p class="text-muted mb-0">Publica artículos y novedades del sitio.</p></div><a class="btn btn-primary" href="<?= e(url('admin/noticias/nueva')) ?>"><i class="bi bi-plus-lg me-1"></i>Nueva noticia</a></div><div class="admin-card card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Título</th><th>Autor</th><th>Estado</th><th>Fecha</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach ($news as $article): ?><tr><td><strong><?= e((string) $article['title']) ?></strong><br><small class="text-muted">/<?= e((string) $article['slug']) ?></small></td><td><?= e((string) ($article['author_name'] ?? '')) ?></td><td><?= e((string) $article['status']) ?></td><td><?= e((string) ($article['scheduled_at'] ?: $article['published_at'] ?: '')) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= e(url('admin/noticias/' . (int) $article['id'] . '/editar')) ?>">Editar</a><form method="post" action="<?= e(url('admin/noticias/' . (int) $article['id'])) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger" type="submit" onclick="return confirm('La noticia saldrá del blog público. No se borra: podrás recuperarla durante 30 días. ¿Continuar?');">Papelera</button></form></td></tr><?php endforeach; ?><?php if ($news === []): ?><tr><td colspan="5" class="text-center py-4">Todavía no hay noticias.</td></tr><?php endif; ?></tbody></table></div></div>